SELECT r.id AS registerId, r.case_number AS caseNumber, r.real_name AS realName, r.gender AS gender, r.age AS age, dep.dept_name AS deptName, lv.regist_name AS registLevelName, DATE_FORMAT(r.visit_date, '%Y-%m-%d %H:%i') AS visitDate, r.noon AS noon, r.visit_state AS visitState, IFNULL((SELECT SUM(f2.fee_amount) FROM fee_record f2 WHERE f2.register_id = r.id AND f2.fee_type = '收费'), 0) AS chargeAmount FROM register r LEFT JOIN department dep ON r.department_id = dep.id LEFT JOIN regist_level lv ON r.regist_level_id = lv.id
AND r.case_number = #{caseNumber}
AND r.real_name LIKE CONCAT('%', #{realName}, '%')
AND DATE(r.visit_date) >= #{startDate}
AND DATE(r.visit_date) <= #{endDate}
ORDER BY r.visit_date DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM register r


        AND r.case_number = #{caseNumber}


        AND r.real_name LIKE CONCAT('%', #{realName}, '%')


        AND DATE(r.visit_date) >= #{startDate}


        AND DATE(r.visit_date) <= #{endDate}
